overlaps(bounds: RotatedBounds, other: CanvasBounds): boolean {
  const onScreenAxes = overlapsEnclosing(
    (ratio) => RotatedBounds.pointAt(bounds, ratio),
    other,
  );
  const onRotatedAxes = overlapsEnclosing(
    (ratio) =>
      RotatedBounds.unrotatePoint(bounds, CanvasBounds.pointAt(other, ratio)),
    bounds.unrotated,
  );
  return onScreenAxes && onRotatedAxes;
},

enclosing(boundsList: readonly CanvasBounds[]): Option<CanvasBounds> {
  if (boundsList.length === 0) {
    return Option.none;
  }
  const [first, ...rest] = boundsList;
  return Option.some(CanvasBounds.enclosingAll([first, ...rest]));
},

/**
 * 1 つ以上の矩形をすべて含む最小の矩形（`enclosing` の、空になりえない並びを受ける形）。
 *
 * @param boundsList 含めたい矩形の並び。1 件目は必ずある
 * @returns すべてを含む最小の矩形
 */
enclosingAll(
  boundsList: readonly [CanvasBounds, ...CanvasBounds[]],
): CanvasBounds {
  const [first, ...rest] = boundsList;
  const enclosed = rest.reduce(
    (widest, bounds) => ({
      left: Math.min(widest.left, bounds.left),
      top: Math.min(widest.top, bounds.top),
      right: Math.max(widest.right, CanvasBounds.edge(bounds, Axes.Width)),
      bottom: Math.max(widest.bottom, CanvasBounds.edge(bounds, Axes.Height)),
    }),
    {
      left: first.left,
      top: first.top,
      right: CanvasBounds.edge(first, Axes.Width),
      bottom: CanvasBounds.edge(first, Axes.Height),
    },
  );
  return {
    left: enclosed.left,
    top: enclosed.top,
    width: enclosed.right - enclosed.left,
    height: enclosed.bottom - enclosed.top,
  };
},

measureRotated(
  name: string,
  rotation: Angle,
  view: CanvasView,
): Option<RotatedBounds> {
  return Option.flatMap(CanvasDom.elementOf(name), (element) => {
    const enclosing = CanvasDom.boundsOf(element);
    if (Angle.isWholeTurns(rotation)) {
      return Option.some(
        RotatedBounds.fromEnclosing(enclosing, enclosing, rotation),
      );
    }
    return Option.map(CanvasDom.layoutSizeOf(element), (size) => {
      const drawn = CanvasView.toScreenOffset(view, {
        x: size.width,
        y: size.height,
      });
      return RotatedBounds.fromEnclosing(
        enclosing,
        { width: drawn.x, height: drawn.y },
        rotation,
      );
    });
  });
},

collectArtboardChildRotations(
  document: DesignDocument,
): readonly NamedRotation[] {
  return document.artboards.flatMap((artboard) => {
    const outer = Rotation.fromProps(Artboard.boxProps(artboard));
    return artboard.children.flatMap((child) => {
      const own = rootPropsOf(document, child);
      return Option.isSome(own)
        ? [
            {
              name: child.name,
              rotation: outer + Rotation.fromProps(own.value),
            },
          ]
        : [];
    });
  });
},

/**
 * その範囲に重なって描かれている、選べるものの名前。
 *
 * 候補はドキュメントが答え（artboard 直下の子）、そのうちどれが重なっているかは、向きは
 * ドキュメントが、位置と大きさは実測が答える。
 *
 * @param designDocument 候補と向きの出どころ
 * @param range 重なりを見る範囲
 * @param view レイアウトの大きさを画面上の大きさへ直す倍率
 * @returns 重なって描かれているものの名前。1 つも無ければ空
 */
function namesWithin(
  designDocument: DesignDocument,
  range: RangeSelect,
  view: CanvasView,
): readonly string[] {
  return DrawnBounds.collectOverlappingNames(
    DesignDocument.collectArtboardChildRotations(designDocument),
    RangeSelect.bounds(range),
    view,
  );
}

/**
 * 4 角を写した先を囲む軸に平行な矩形が、相手の矩形と重なっているか。
 *
 * @param pointOf 矩形の中の比率（左上 (0, 0)・右下 (1, 1)）で指した角を写す先
 * @param other 重なりを見る相手の矩形
 * @returns 写した 4 角を囲む矩形が相手と少しでも重なっていれば `true`
 */
function overlapsEnclosing(
  pointOf: (ratio: Offset) => Offset,
  other: CanvasBounds,
): boolean {
  const enclosing = CanvasBounds.enclosingAll([
    CanvasBounds.spanning(pointOf({ x: 0, y: 0 }), pointOf({ x: 1, y: 1 })),
    CanvasBounds.spanning(pointOf({ x: 1, y: 0 }), pointOf({ x: 0, y: 1 })),
  ]);
  return CanvasBounds.overlaps(enclosing, other);
}

/**
 * 矩形の中の比率で指した点。
 *
 * @param bounds 点を指す矩形
 * @param ratio 矩形の左上を (0, 0)、右下を (1, 1) とした比率
 * @returns その比率の位置にある点（画面上の px）
 */
pointAt(bounds: CanvasBounds, ratio: Offset): Offset {
  return {
    x: bounds.left + bounds.width * ratio.x,
    y: bounds.top + bounds.height * ratio.y,
  };
},

/**
 * 名前で指した要素の、回る前の矩形が面積を持つときの矩形と向き。
 *
 * 要素が在っても、描かれる前や器が畳まれているときの実測は大きさ 0 で返る
 * （`CanvasBounds.hasArea` の doc）。そこに何かがあるとみなすと、見えていないものを範囲
 * 選択やスナップが拾ってしまう。
 *
 * @param name 描かれている artboard / ノードの名前
 * @param rotation その名前のものの画面上の向き（自分と祖先の合計）
 * @param view レイアウトの大きさを画面上の大きさへ直す倍率
 * @returns 回る前の矩形と向き。`measureRotated` が `none` のときと、回る前の矩形が面積を
 *   持たないときは `none`
 */
function measureRotatedWithArea(
  name: string,
  rotation: Angle,
  view: CanvasView,
): Option<RotatedBounds> {
  return Option.flatMap(
    DrawnBounds.measureRotated(name, rotation, view),
    (measured) =>
      CanvasBounds.hasArea(measured.unrotated)
        ? Option.some(measured)
        : Option.none,
  );
}

/**
 * すべての artboard の**直下の子**の名前と、画面上の向き（範囲選択が選びうる相手と、
 * その当たり判定に使う向き）。
 *
 * 直下だけで止めるのは、キャンバスから選べる階層がそこだから（掘るのはダブルクリック
 * の担当 / docs/06-ui.md「キャンバスのクリックが選ぶ階層」）。孫まで集めると、範囲で払
 * ったときにクリックとは違う階層が選ばれる。
 *
 * 参照先の部品が無いインスタンスは向きが決まらないので外す。そのドキュメントはコンパイル
 * 全体が失敗してキャンバスに名前の付いた要素が描かれないので、外しても選ばれる相手は変わらない。
 *
 * @param document 走査するドキュメント
 * @returns artboard の並び順・子の並び順のままの名前と、artboard と子の角度の合計
 *   （`totalRotationOf` と同じ値）。1 つも無ければ空
 */
collectArtboardChildRotations(
  document: DesignDocument,
): readonly NamedRotation[] {
  return document.artboards.flatMap((artboard) => {
    const outer = Rotation.fromProps(Artboard.boxProps(artboard));
    return artboard.children.flatMap((child) => {
      const own = rootPropsOf(document, child);
      return Option.isSome(own)
        ? [
            {
              name: child.name,
              rotation: outer + Rotation.fromProps(own.value),
            },
          ]
        : [];
    });
  });
},
